"""Português — fé e culto (faith_001 … faith_070)."""

T = {
"faith_001": ("Quantos pilares tem o islão?", ["5", "4", "6", "7"], "O hadith de Jibril e o hadith narrado por Ibn Umar enumeram os cinco pilares do islão."),
"faith_002": ("Como se chama a declaração de fé no islão?", ["A Shahada", "A Salat", "O Zakat", "O Hajj"], "A Shahada, o testemunho de fé, é o primeiro pilar do islão."),
"faith_003": ("Quantas vezes por dia se faz a oração obrigatória no islão?", ["5", "3", "4", "7"], "As cinco orações diárias obrigatórias são um pilar fundamental do islão."),
"faith_004": ("Como se chama a esmola obrigatória no islão?", ["Zakat", "Sadaqa", "Waqf", "Kaffara"], "O zakat é a esmola obrigatória, um dos cinco pilares do islão."),
"faith_005": ("Como se chama o mês de jejum obrigatório no islão?", ["Ramadão", "Shawwal", "Rajab", "Muharram"], "O Alcorão ordena o jejum durante o mês do Ramadão."),
"faith_006": ("Como se chama a peregrinação a Meca, obrigatória uma vez na vida para quem puder?", ["Hajj", "Umra", "I'tikaf", "Tawaf"], "O Alcorão torna o Hajj obrigatório, pelo menos uma vez na vida, para quem o puder realizar."),
"faith_007": ("Para que direção se voltam os muçulmanos para rezar?", ["A Ka'ba, em Meca", "Jerusalém", "Medina", "O leste"], "O Alcorão estabeleceu a Ka'ba como direção da oração (qibla)."),
"faith_008": ("Segundo um hadith muito conhecido, quantos artigos de fé (pilares do iman) se ensinam habitualmente?", ["6", "4", "5", "7"], "O hadith de Jibril enumera seis artigos de fé: Allah, os anjos, os livros, os mensageiros, o Último Dia e o decreto divino."),
"faith_009": ("Como se chama a purificação com água que o muçulmano faz antes de cada oração?", ["Wudu (ablução)", "Tayammum", "Ghusl", "Siwak"], "«Quando vos levantardes para a oração, lavai o rosto e as mãos…»: é o wudu."),
"faith_010": ("Segundo o Alcorão, o que fazem os «nobres escribas» (kiraman katibin)?", ["Registam as ações das pessoas", "Carregam o Trono", "Guardam o Paraíso", "Trazem a chuva"], "«Sobre vós há guardiães, nobres escribas»: os anjos registam cada ação."),
"faith_011": ("Quantos belos nomes de Allah transmite a tradição autêntica?", ["99", "50", "100", "114"], "Um hadith autêntico narrado por al-Bukhari e Muslim menciona noventa e nove nomes: cem menos um."),
"faith_012": ("O que significa o nome de Allah «Ar-Rahman»?", ["O Misericordioso", "O Criador", "O Rei", "O Omnisciente"], "Ar-Rahman, o Misericordioso: a Sua misericórdia abrange todas as coisas."),
"faith_013": ("Em Al-Fatiha, de que dia é Allah chamado «Senhor»?", ["Do Dia do Juízo", "Da sexta-feira", "Do primeiro dia", "Do dia de Arafa"], "«Senhor do Dia do Juízo»: o dia em que cada um encontra as suas obras."),
"faith_014": ("Em que dia da semana chama o Alcorão os crentes à oração em comum?", ["Sexta-feira", "Segunda-feira", "Sábado", "Domingo"], "«Quando se chamar à oração na sexta-feira, apressai-vos para a lembrança de Allah.»"),
"faith_015": ("Segundo o Alcorão, quem garante a preservação do Alcorão contra qualquer alteração?", ["O próprio Allah", "Apenas os anjos", "Os sábios", "Os reis"], "«Na verdade, fizemos descer a Lembrança, e somos o seu Guardião.»"),
"faith_016": ("O que declara o Alcorão sobre a entrada na religião?", ["Não há coação na religião", "Faz-se por juramento", "Requer uma testemunha", "Acontece na idade adulta"], "«Não há coação na religião: a guia reta distingue-se do erro.»"),
"faith_017": ("Qual é a saudação dos muçulmanos, um desejo de paz?", ["As-salamu alaykum", "Marhaban", "Sabah al-khayr", "Ahlan wa sahlan"], "«As-salamu alaykum»: a paz esteja convosco; responde-se «wa alaykum as-salam»."),
"faith_018": ("Como se chama a crença na unicidade de Allah, coração do islão?", ["Tawhid", "Tafsir", "Tajwid", "Tarawih"], "O tawhid, afirmar que Allah é Único, sem associado, é o fundamento de toda a fé."),
"faith_019": ("Que Livro revelou Allah ao profeta Musa?", ["A Tawrat (Torá)", "O Injil (Evangelho)", "O Zabur (Salmos)", "O Alcorão"], "«Fizemos descer a Tawrat, na qual há guia e luz» (5:44)."),
"faith_020": ("Que Livro deu Allah ao profeta Isa?", ["O Injil (Evangelho)", "A Tawrat", "O Zabur", "As Folhas de Ibrahim"], "«Demos-lhe o Injil, no qual há guia e luz» (5:46)."),
"faith_021": ("Segundo o Alcorão, o que se deve fazer ao receber uma saudação?", ["Responder com uma saudação melhor, ou devolvê-la", "Ficar em silêncio", "Baixar os olhos", "Responder só aos amigos"], "«Quando vos saudarem, saudai com uma saudação melhor, ou devolvei-a» (4:86)."),
"faith_022": ("A surata Al-A'la menciona «as Folhas» (suhuf) de que dois profetas?", ["Ibrahim e Musa", "Nuh e Hud", "Dawud e Sulayman", "Zakariyya e Yahya"], "«Isto está nas Folhas primeiras, as Folhas de Ibrahim e de Musa» (87:18-19)."),
"faith_023": ("Como se chama o anjo guardião do Inferno, mencionado no Alcorão?", ["Malik", "Ridwan", "Mika'il", "Israfil"], "A gente do Inferno gritará: «Ó Malik, que o teu Senhor acabe connosco!» (43:77)."),
"faith_024": ("Segundo a surata Al-Haqqa, quantos anjos carregarão o Trono de Allah no Dia da Ressurreição?", ["Oito", "Quatro", "Doze", "Um"], "«E nesse Dia, oito carregarão sobre eles o Trono do teu Senhor» (69:17)."),
"faith_025": ("Segundo o Alcorão, quem está encarregado de recolher as almas no momento da morte?", ["O anjo da morte", "Jibril", "O profeta", "Os génios"], "«Diz: o anjo da morte, encarregado de vós, recolherá as vossas almas» (32:11)."),
"faith_026": ("De que foram criados os anjos, segundo um hadith de Sahih Muslim?", ["De luz", "De fogo", "De argila", "De água"], "«Os anjos foram criados de luz, os génios de fogo sem fumo, e Adam do que vos foi descrito.»"),
"faith_027": ("De que foram criados os génios, segundo o Alcorão?", ["De fogo sem fumo", "De luz", "De argila", "De vento"], "«E criou os génios de uma chama de fogo sem fumo» (55:15)."),
"faith_028": ("Quem aponta o Alcorão como inimigo declarado do ser humano?", ["Satanás (ash-Shaytan)", "Os anjos", "Os animais", "A noite"], "«Na verdade, Satanás é vosso inimigo; tomai-o, pois, como inimigo» (35:6)."),
"faith_029": ("Quantos profetas são chamados «Ulu al-Azm» (os dotados de firmeza)?", ["Cinco: Nuh, Ibrahim, Musa, Isa e Muhammad ﷺ", "Três", "Dez", "Vinte e cinco"], "«Sê paciente como o foram os mensageiros dotados de firmeza» (46:35); a surata Ash-Shura (42:13) nomeia estes cinco juntos."),
"faith_030": ("Em que se soprará para anunciar a Ressurreição, segundo o Alcorão?", ["Na Trombeta (as-Sur)", "Num corno de carneiro", "Numa flauta", "Num sino"], "«Soprar-se-á na Trombeta, e quem estiver nos céus e na terra cairá fulminado… depois soprar-se-á de novo» (39:68)."),
"faith_031": ("Como chama o Alcorão ao que pesará as obras no Dia da Ressurreição?", ["As balanças (al-Mawazin)", "O registo", "A ponte", "A trombeta"], "«Colocaremos as balanças justas no Dia da Ressurreição; ninguém será tratado injustamente em nada» (21:47)."),
"faith_032": ("Que nome dá o Alcorão ao grau mais alto do Paraíso, prometido aos que creem e praticam o bem?", ["Al-Firdaws", "Al-Kawthar", "As-Sirat", "Al-A'raf"], "«Os que creem e praticam o bem terão por morada os Jardins do Firdaws» (18:107)."),
"faith_033": ("Qual é o nome mais frequente do Inferno no Alcorão?", ["Jahannam", "Firdaws", "Kawthar", "Tasnim"], "O Alcorão chama ao Inferno «Jahannam» dezenas de vezes, por exemplo: «Sereis congregados para Jahannam» (3:12)."),
"faith_034": ("Que pilar da fé afirma o versículo «Criámos todas as coisas com medida»?", ["A crença no decreto divino (al-qadar)", "A crença nos anjos", "A crença nos Livros", "A crença nos mensageiros"], "«Criámos todas as coisas segundo uma medida (qadar)» (54:49): nada acontece fora do conhecimento e da vontade de Allah."),
"faith_035": ("Que pecado declara Allah não perdoar a quem morre sem dele se arrepender?", ["O shirk (associar algo a Allah)", "A mentira", "A avareza", "A ira"], "«Allah não perdoa que Lhe associem nada, e perdoa o que é menos do que isso a quem Ele quer» (4:48)."),
"faith_036": ("Segundo o Alcorão, quem ama Allah entre os que pecaram?", ["Os que se arrependem", "Os que escondem os pecados", "Os que desesperam", "Os que culpam os outros"], "«Na verdade, Allah ama os que se arrependem e ama os que se purificam» (2:222)."),
"faith_037": ("Segundo a surata Nuh, o que traz a um povo pedir perdão (istighfar)?", ["Chuva abundante e bênçãos", "Nada", "Uma seca", "Um longo sono"], "«Pedi perdão ao vosso Senhor, que é muito Perdoador; enviará sobre vós o céu com chuva abundante» (71:10-11)."),
"faith_038": ("O que promete o Alcorão a quem põe a sua confiança em Allah (tawakkul)?", ["Allah basta-lhe", "Ficará rico", "Nunca adoecerá", "Já não terá de trabalhar"], "«E quem confia em Allah, Ele basta-lhe» (65:3)."),
"faith_039": ("O que diz Allah sobre a súplica (du'a) na surata Ghafir?", ["«Invocai-Me, responder-vos-ei»", "«Invocai só de noite»", "«Invocai os anjos»", "«A du'a é só para os profetas»"], "«O vosso Senhor diz: Invocai-Me, responder-vos-ei» (40:60)."),
"faith_040": ("Com que, segundo o Alcorão, encontram os corações sossego?", ["Com a lembrança de Allah (dhikr)", "Com o dinheiro", "Com o sono", "Com as viagens"], "«Não é com a lembrança de Allah que os corações se tranquilizam?» (13:28)."),
"faith_041": ("Qual é a primeira oração obrigatória do dia?", ["Al-Fajr (a alvorada)", "Adh-Dhuhr (meio-dia)", "Al-Asr (a tarde)", "Al-Isha (a noite)"], "As cinco orações são, por ordem: Fajr, Dhuhr, Asr, Maghrib e Isha."),
"faith_042": ("Quantas rak'a tem a oração obrigatória do Fajr?", ["Duas", "Três", "Quatro", "Uma"], "O Fajr tem duas rak'a; o Maghrib três; Dhuhr, Asr e Isha quatro cada uma."),
"faith_043": ("Que oração obrigatória tem três rak'a?", ["Al-Maghrib", "Al-Fajr", "Adh-Dhuhr", "Al-Isha"], "O Maghrib, logo após o pôr do sol, é a única oração obrigatória de três rak'a."),
"faith_044": ("Como se chama a chamada à oração feita a partir da mesquita?", ["O adhan", "A khutba", "O tasbih", "A talbiya"], "O adhan é feito pelo muezim (mu'adhdhin) antes de cada uma das cinco orações."),
"faith_045": ("Segundo o versículo da ablução, até onde se devem lavar os braços?", ["Até aos cotovelos", "Até aos pulsos", "Até aos ombros", "Só as mãos"], "«Lavai o rosto e as mãos até aos cotovelos, passai as mãos pela cabeça e lavai os pés até aos tornozelos» (5:6)."),
"faith_046": ("O que permite o Alcorão quando não se encontra água para a purificação antes da oração?", ["O tayammum com terra limpa", "Rezar sem purificação", "Adiar a oração para o dia seguinte", "Lavar-se com areia molhada"], "«Se não encontrardes água, recorrei a terra limpa e passai-a pelo rosto e pelas mãos» (5:6)."),
"faith_047": ("Como se chama o sermão que o imã profere antes da oração de sexta-feira?", ["A khutba", "O adhan", "A iqama", "O takbir"], "A khutba de sexta-feira é proferida em duas partes a partir do minbar, antes da oração."),
"faith_048": ("Que parte das suas poupanças, guardadas durante um ano inteiro, entrega o muçulmano como zakat?", ["2,5 %", "10 %", "25 %", "1 %"], "O zakat do dinheiro poupado é um quarto do dízimo, 2,5 %, quando ultrapassa o limiar (nisab) durante um ano lunar."),
"faith_049": ("Que esmola particular é devida no fim do Ramadão, antes da oração do Eid?", ["O zakat al-fitr", "O zakat do ouro", "O khums", "A kaffara"], "O Profeta ﷺ tornou obrigatório o zakat al-fitr, um sa' de tâmaras ou cevada, para cada muçulmano, pequeno ou grande."),
"faith_050": ("Segundo o Alcorão, desde quando até quando dura o jejum diário do Ramadão?", ["Desde a alvorada até à noite", "Desde o meio-dia até à tarde", "Desde o nascer do sol até ao meio-dia", "Todo o dia e toda a noite"], "«Comei e bebei até que se distinga o fio branco da alvorada do fio negro, depois completai o jejum até à noite» (2:187)."),
"faith_051": ("Como se chama a refeição tomada antes da alvorada por quem vai jejuar?", ["O suhur", "O iftar", "A walima", "A aqiqa"], "O Profeta ﷺ disse: «Tomai o suhur, pois no suhur há bênção»."),
"faith_052": ("Como se chama a refeição com que se quebra o jejum ao pôr do sol?", ["O iftar", "O suhur", "O tarawih", "O tahajjud"], "O iftar quebra o jejum assim que o sol se põe, à hora da oração do Maghrib."),
"faith_053": ("Quantas festas (Eid) tem o islão no ano?", ["Duas: o Eid al-Fitr e o Eid al-Adha", "Apenas uma", "Quatro", "Doze"], "O Eid al-Fitr encerra o mês do Ramadão; o Eid al-Adha cai a 10 de Dhul-Hijja, durante a peregrinação."),
"faith_054": ("Que acontecimento comemora o Eid al-Adha?", ["O sacrifício de Ibrahim, resgatado com um carneiro", "O nascimento do Profeta ﷺ", "A batalha de Badr", "A revelação do Alcorão"], "Pronto a sacrificar o filho, Ibrahim viu-o resgatado: «Resgatámo-lo com um grande sacrifício» (37:107)."),
"faith_055": ("Em que mês do calendário islâmico se realiza a peregrinação (hajj)?", ["Dhul-Hijja", "Ramadão", "Muharram", "Rajab"], "O hajj realiza-se de 8 a 13 de Dhul-Hijja, o décimo segundo e último mês do ano lunar."),
"faith_056": ("Em que dia de Dhul-Hijja se detêm os peregrinos na planície de Arafat?", ["No dia 9", "No dia 1", "No dia 10", "No dia 27"], "A permanência em Arafat, a 9 de Dhul-Hijja, é o pilar central do hajj; o Eid al-Adha chega no dia seguinte."),
"faith_057": ("Quantas voltas à Ka'ba tem um tawaf?", ["Sete", "Três", "Cinco", "Dez"], "O tawaf são sete voltas à Ka'ba, no sentido contrário ao dos ponteiros do relógio, a começar na Pedra Negra."),
"faith_058": ("Quantos percursos entre As-Safa e Al-Marwa tem o sa'y?", ["Sete", "Dois", "Quatro", "Doze"], "O sa'y recorda a procura de água de Hajar para Isma'il: sete percursos, de Safa a Marwa e de volta, contando cada sentido."),
"faith_059": ("Como se chama o estado de consagração em que entra o peregrino, com os seus dois panos brancos?", ["O ihram", "O tawaf", "O wuquf", "A talbiya"], "Em ihram, o homem veste dois panos sem costura e o peregrino abstém-se de perfume, caça e disputas."),
"faith_060": ("Com que palavras começa a talbiya, que os peregrinos repetem a caminho de Meca?", ["«Labbayka Allahumma labbayk» (Aqui estou, ó Allah, aqui estou)", "«Allahu akbar»", "«Subhana Allah»", "«Al-hamdu li-Llah»"], "A talbiya do Profeta ﷺ era: «Labbayka Allahumma labbayk, labbayka la sharika laka labbayk…»."),
"faith_061": ("O que fazem os peregrinos em Mina quando lançam pedrinhas contra três pilares?", ["O apedrejamento das jamarat", "O tawaf", "O sa'y", "A permanência em Arafat"], "O ramy al-jamarat recorda Ibrahim a afugentar Satanás com pedras; faz-se em Mina nos dias do Eid."),
"faith_062": ("Onde está a Pedra Negra (al-Hajar al-Aswad)?", ["Num canto da Ka'ba", "No monte Arafat", "Em Medina", "No cimo do monte Hira"], "Engastada no canto oriental da Ka'ba, marca o ponto de partida de cada volta do tawaf."),
"faith_063": ("Como se chama o grande pano preto que cobre a Ka'ba?", ["A kiswa", "O hijab", "O minbar", "O mihrab"], "A kiswa, bordada com versículos em fio de ouro, é substituída todos os anos durante a peregrinação."),
"faith_064": ("Como se chama a peregrinação «menor» a Meca, que pode ser feita em qualquer altura do ano?", ["A umra", "O hajj", "A hégira", "A ziyara"], "A umra consiste em ihram, tawaf e sa'y; ao contrário do hajj, não está ligada a um mês específico."),
"faith_065": ("O que significa o nome de Allah «Al-Khaliq»?", ["O Criador", "O Perdoador", "O Provedor", "O Rei"], "«Ele é Allah, o Criador (al-Khaliq), o Iniciador, o Formador» (59:24)."),
"faith_066": ("O que significa o nome de Allah «Al-Ghafur»?", ["O que muito perdoa", "O Criador", "O Todo-Poderoso", "O Generoso"], "«Não desespereis da misericórdia de Allah… Ele é o Perdoador (al-Ghafur), o Misericordioso» (39:53)."),
"faith_067": ("O que significam os dois nomes de Allah «As-Sami'» e «Al-Basir»?", ["O que tudo ouve e o que tudo vê", "O Rei e o Juiz", "O Criador e o Provedor", "O Primeiro e o Último"], "O versículo da Viagem Noturna termina: «Ele é o Ouvinte (as-Sami'), o Vidente (al-Basir)» (17:1)."),
"faith_068": ("O que significa «As-Samad», nome de Allah na surata Al-Ikhlas?", ["Aquele de quem tudo depende e que de nada depende", "O que perdoa", "O que ouve", "O que cria"], "«Allahu as-Samad» (112:2): o Senhor absoluto a quem todas as criaturas recorrem nas suas necessidades."),
"faith_069": ("Que dois nomes de Allah abrem o Versículo do Trono, logo a seguir a «Allah, não há deus senão Ele»?", ["Al-Hayy e Al-Qayyum (o Vivente, o Subsistente)", "Ar-Rahman e Ar-Rahim", "Al-Malik e Al-Quddus", "Al-Aziz e Al-Hakim"], "«Allah! Não há deus senão Ele, o Vivente, o Subsistente» (2:255)."),
"faith_070": ("O que significa o nome de Allah «Ar-Razzaq»?", ["O Grande Provedor", "O Perdoador", "O Justo", "O Subtil"], "«Na verdade, Allah é o Provedor (ar-Razzaq), o Dono da força, o Firme» (51:58)."),
}
